// 1. Recursive Function Template Expansion (Pre-C++17 style)
// Defines the variadic pack (Types...)
template <typename T, typename... Types>
void process(T head, Types... tail) {
    // head: first argument (T)
    // tail: remaining pack of arguments (Types...)

    // Operation on head
    head = 42;

    // Pack Expansion: Recurse on remaining pack
    process(tail...);
}

// Base case (stops recursion when pack is empty)
void process() {}


// 2. C++17 Fold Expression (Direct Expansion)
template <typename... Args>
auto sum_all(Args... args) {
    // Unary Right Fold: Initial value is 0 (for '+')
    // Expands: (arg1 + (arg2 + (arg3 + ...)))
    return (args + ...);
}

template <typename T, typename... Args>
bool all_true(T first, Args... conditions) {
    // Binary Left Fold: (Initial E op ... op Pack)
    // Expands: (((first && cond1) && cond2) && ...)
    return (first && ... && conditions);
}
